'use strict';
// 全局错误/未处理 promise 捕获，用于定位类似扩展引起的异步响应通道错误
let _kfSystemReady = false; // 关键帧系统是否已初始化（防止 TDZ 问题）
window.addEventListener('unhandledrejection', (ev) => {
    try {
        console.warn('UnhandledPromiseRejection captured:', ev.reason);
        // 如果来自扩展，其堆栈或消息常包含 chrome-extension:// 前缀
        if (ev.reason && ev.reason.stack) console.warn(ev.reason.stack);
    } catch (e) { console.warn('Error logging unhandledrejection', e); }
});
window.addEventListener('error', (ev) => {
    try {
        console.warn('Global error captured:', ev.message, ev.filename, ev.lineno, ev.colno);
    } catch (e) { /* ignore */ }
});
// 内嵌方块创建菜单图标（256×256 源图压缩为 24×24 显示）
const ICON_CUBE = 'data:image/png;base64,';
const ICON_STAIR = 'data:image/png;base64,';
const ICON_SLAB = 'data:image/png;base64,';
const ICON_FLAG = 'data:image/png;base64,';
const ICON_PLANE = 'data:image/png;base64,';


// ============================================================
// 通用复制函数（优先使用原生接口，解决国产手机复制问题）
// ============================================================
function copyToClipboard(text, successMsg) {
    successMsg = successMsg || '已复制到剪贴板';

    // 1. 优先使用 Android 原生接口（最可靠）
    if (window.Android && typeof window.Android.copyText === 'function') {
        window.Android.copyText(text);
        showToast(successMsg);
        return;
    }

    // 2. 其次使用 Clipboard API（现代浏览器）
    if (navigator.clipboard && navigator.clipboard.writeText) {
        navigator.clipboard.writeText(text).then(() => {
            showToast(successMsg);
        }).catch(() => {
            fallbackCopy(text, successMsg);
        });
        return;
    }

    // 3. 否则使用 execCommand（旧方案）
    fallbackCopy(text, successMsg);
}

function fallbackCopy(text, successMsg) {
    const textarea = document.createElement('textarea');
    textarea.value = text;
    textarea.style.position = 'fixed';
    textarea.style.opacity = '0';
    textarea.style.left = '-9999px';
    textarea.style.top = '-9999px';
    textarea.style.pointerEvents = 'none';
    document.body.appendChild(textarea);
    textarea.select();
    try {
        const success = document.execCommand('copy');
        if (success) {
            showToast(successMsg);
        } else {
            manualCopyFallback(text);
        }
    } catch (e) {
        manualCopyFallback(text);
    }
    document.body.removeChild(textarea);
}

function manualCopyFallback(text) {
    // 显示可复制文本框，让用户长按复制
    showModal('复制内容',
        '<textarea style="width:100%;min-height:80px;padding:8px;background:#1e293b;color:white;border:1px solid #3b82f6;border-radius:8px;font-size:14px;font-family:monospace;resize:vertical;" readonly>' +
        escapeHtml(text) +
        '</textarea><p style="font-size:12px;color:#94a3b8;margin-top:8px;">请长按上方文字选择复制</p>',
        null, false);
}

function showToast(msg, opts = {}) {
    // 通用科技泡泡的 toast 形态：无按钮、按 duration 自动炸开消失，复用管线动画与浅蓝菱形呼吸灯
    return showTechBubble('', msg, { mode: 'toast', duration: opts.duration || 2000, variant: opts.variant || 'info' });
}

